// Server-side opaque sync storage. The server authenticates accounts but never receives
// notes, labels, images, tombstones, or any decryptable user payload.
import type { Client, Transaction } from '@libsql/client/web';
import { env } from '$env/dynamic/private';
import { ACTIVITY_WINDOWS_DAYS } from '$lib/server/operatorConfig';
import { getDb, withTxn, type Db } from '$lib/server/db';

/** `slot` is an opaque, keyed identifier generated by the client for a logical record.
 * It lets the relay replace an old ciphertext without learning whether it is a note, image, etc. */
export type EncryptedEnvelope = { seq: number; id: string; ciphertext: string; slot: string };
export type OpaqueUpload = Omit<EncryptedEnvelope, 'seq'> & { expectedId?: string | null };
export type OpaqueDelete = { id: string; slot: string };

export type SyncResult = {
	cursor: number;
	envelopes: EncryptedEnvelope[];
	conflicts: EncryptedEnvelope[];
	hasMore: boolean;
	reset: boolean;
	writesAccepted: boolean;
};

export type SyncStoreOptions = {
	maxAccountBytes?: number;
};

type AccountRow = {
	credential_hash: string;
	next_seq: number;
	envelope_count: number;
	ciphertext_bytes: number;
	wake_revision: number;
};

export type AccountByteQuota = {
	maxBytes: number;
	overridden: boolean;
};

type UsageRow = {
	envelopeCount: number;
	ciphertextBytes: number;
	storageBytes: number;
};

export type SyncQuotas = {
	maxAccountBytes: number;
};

export type OperatorUsage = UsageRow & {
	accounts: number;
	activeByWindowDays: Record<string, number>;
	staleAccounts: number;
};

const DEFAULT_MAX_ACCOUNT_BYTES = 1_000_000_000;
/** Conservative allowance for row, key, and index storage beyond the ciphertext itself. */
export const ENVELOPE_STORAGE_OVERHEAD_BYTES = 512;
export const MAX_PUSH_DEVICES = 32;
export const MAX_WAKES_PER_ACCOUNT = 1_000;
export const WAKE_RETAIN_MS = 24 * 60 * 60 * 1000;
export const WAKE_CLAIM_LEASE_MS = 60_000;
/** Grace window keeping staged slot deletions recoverable while slower devices catch up. */
export const DELETED_SLOT_GRACE_MS = 14 * 24 * 60 * 60 * 1000;
/** Bound for IN (...) lists so sweeps stay under the SQLite host-parameter limit. */
const ACCOUNT_CHUNK = 400;

export type PushDeviceInput = {
	deviceId: string;
	endpoint: string;
	p256dh: string;
	auth: string;
	accountId: string;
};

export type DueWake = {
	accountId: string;
	deviceId: string;
	wakeId: string;
	fireAt: number;
	endpoint: string;
	p256dh: string;
	auth: string;
};

export type ReminderWakeInput = { id: string; fireAt: number };

/** ASCII-only ciphertext keeps JS `.length` equal to SQLite `length()` for quota math. */
const BASE64URL = /^[A-Za-z0-9_-]+$/;

export class SyncQuotaExceededError extends Error {
	constructor() {
		super('Sync account storage quota exceeded');
		this.name = 'SyncQuotaExceededError';
	}
}

function positiveInteger(value: string | undefined, fallback: number): number {
	const parsed = Number(value);
	return Number.isSafeInteger(parsed) && parsed > 0 ? parsed : fallback;
}

function chunk<T>(values: T[]): T[][] {
	const chunks: T[][] = [];
	for (let offset = 0; offset < values.length; offset += ACCOUNT_CHUNK) {
		chunks.push(values.slice(offset, offset + ACCOUNT_CHUNK));
	}
	return chunks;
}

export class SyncStore {
	private readonly db: Db;
	private readonly maxAccountBytes: number;

	constructor(db: Db, options: SyncStoreOptions = {}) {
		this.db = db;
		this.maxAccountBytes = options.maxAccountBytes ?? DEFAULT_MAX_ACCOUNT_BYTES;
	}

	private get relay(): Client {
		return this.db.relay;
	}

	private get ops(): Client {
		return this.db.ops;
	}

	async getAuthCredential(accountId: string): Promise<string | null> {
		await this.db.ready;
		const result = await this.relay.execute({
			sql: 'SELECT credential_hash AS credentialHash FROM accounts WHERE account_id = ?',
			args: [accountId]
		});
		return (
			(result.rows[0] as unknown as { credentialHash: string } | undefined)?.credentialHash ?? null
		);
	}

	async replaceAuthCredential(
		accountId: string,
		expected: string,
		replacement: string
	): Promise<boolean> {
		await this.db.ready;
		const result = await this.relay.execute({
			sql: 'UPDATE accounts SET credential_hash = ?, updated_at = ? WHERE account_id = ? AND credential_hash = ?',
			args: [replacement, Date.now(), accountId, expected]
		});
		return result.rowsAffected === 1;
	}

	async createAccount(
		accountId: string,
		authPublicKey: string,
		updatedAt = Date.now()
	): Promise<boolean> {
		await this.db.ready;
		const result = await this.relay.execute({
			sql: `
			INSERT OR IGNORE INTO accounts(
				account_id, credential_hash, next_seq, envelope_count, ciphertext_bytes, updated_at, last_seen_at
			)
			VALUES (?, ?, 0, 0, 0, ?, ?)
		`,
			args: [accountId, authPublicKey, updatedAt, updatedAt]
		});
		return result.rowsAffected === 1;
	}

	async getAccountByteQuota(accountId: string): Promise<AccountByteQuota | null> {
		await this.db.ready;
		const row = await this.accountByteQuota(this.relay, accountId);
		if (!row) return null;
		return {
			maxBytes: row.maxBytes ?? this.maxAccountBytes,
			overridden: row.maxBytes !== null
		};
	}

	private async accountByteQuota(
		client: Client | Transaction,
		accountId: string
	): Promise<{ maxBytes: number | null } | undefined> {
		const result = await client.execute({
			sql: `SELECT quotas.max_bytes AS maxBytes
				 FROM accounts
				 LEFT JOIN account_quotas AS quotas USING(account_id)
				 WHERE account_id = ?`,
			args: [accountId]
		});
		return result.rows[0] as unknown as { maxBytes: number | null } | undefined;
	}

	async setAccountByteQuota(accountId: string, maxBytes: number): Promise<boolean> {
		if (!Number.isSafeInteger(maxBytes) || maxBytes <= 0) {
			throw new RangeError('Account byte quota must be a positive safe integer');
		}
		await this.db.ready;
		const result = await this.relay.execute({
			sql: `INSERT INTO account_quotas(account_id, max_bytes)
				 SELECT account_id, ? FROM accounts WHERE account_id = ?
				 ON CONFLICT(account_id) DO UPDATE SET max_bytes = excluded.max_bytes`,
			args: [maxBytes, accountId]
		});
		return result.rowsAffected === 1;
	}

	async clearAccountByteQuota(accountId: string): Promise<boolean> {
		if (!(await this.getAuthCredential(accountId))) return false;
		await this.relay.execute({
			sql: 'DELETE FROM account_quotas WHERE account_id = ?',
			args: [accountId]
		});
		return true;
	}

	async sync(
		accountId: string,
		cursor: number,
		uploads: OpaqueUpload[],
		deletions: OpaqueDelete[],
		downloadLimit = 12
	): Promise<SyncResult & { usage: UsageRow & { maxBytes: number } }> {
		await this.db.ready;
		return withTxn(this.relay, async (tx) => {
			const account = (
				await tx.execute({
					sql: `
				SELECT credential_hash AS credentialHash, next_seq AS nextSeq, envelope_count AS envelopeCount,
					ciphertext_bytes AS ciphertextBytes, wake_revision AS wakeRevision
				FROM accounts
				WHERE account_id = ?
			`,
					args: [accountId]
				})
			).rows[0] as unknown as
				| (AccountRow & {
						nextSeq: number;
						envelopeCount: number;
						ciphertextBytes: number;
						wakeRevision: number;
				  })
				| undefined;
			if (!account) throw new Error('Sync account does not exist');
			const quotaRow = await this.accountByteQuota(tx, accountId);
			const maxAccountBytes = quotaRow?.maxBytes ?? this.maxAccountBytes;

			let envelopeCount = account.envelopeCount;
			let ciphertextBytes = account.ciphertextBytes;
			const retained = (
				await tx.execute({
					sql: `SELECT COUNT(*) AS envelopeCount,
						COALESCE(SUM(length(ciphertext)), 0) AS ciphertextBytes
					 FROM deleted_envelopes WHERE account_id = ?`,
					args: [accountId]
				})
			).rows[0] as unknown as { envelopeCount: number; ciphertextBytes: number };
			let retainedEnvelopeCount = retained.envelopeCount;
			let retainedCiphertextBytes = retained.ciphertextBytes;
			const storageBytes = (activeCount = envelopeCount, activeBytes = ciphertextBytes): number =>
				activeBytes +
				retainedCiphertextBytes +
				(activeCount + retainedEnvelopeCount) * ENVELOPE_STORAGE_OVERHEAD_BYTES;
			const usage = (): UsageRow & { maxBytes: number } => ({
				envelopeCount,
				ciphertextBytes,
				storageBytes: storageBytes(),
				maxBytes: maxAccountBytes
			});
			if (cursor > account.nextSeq) {
				// Wake revisions live in cursor space; a sequence reset rewinds that
				// space, so the guard must rewind with it or wake publishing stalls.
				await tx.execute({
					sql: 'UPDATE accounts SET wake_revision = 0 WHERE account_id = ?',
					args: [accountId]
				});
				await this.touchVia(tx, accountId);
				return {
					cursor: 0,
					envelopes: [],
					conflicts: [],
					hasMore: false,
					reset: true,
					writesAccepted: false,
					usage: usage()
				};
			}
			const page = (
				await tx.execute({
					sql: `
				SELECT seq, id, ciphertext, slot
				FROM envelopes
				WHERE account_id = ? AND seq > ?
				ORDER BY seq ASC
				LIMIT ?
			`,
					args: [accountId, cursor, downloadLimit + 1]
				})
			).rows as unknown as EncryptedEnvelope[];
			const hasMore = page.length > downloadLimit;
			const remote = hasMore ? page.slice(0, downloadLimit) : page;
			const attemptedWrites = uploads.length > 0 || deletions.length > 0;
			if (remote.length > 0) {
				await this.touchVia(tx, accountId);
				return {
					cursor: remote.at(-1)?.seq ?? cursor,
					envelopes: remote,
					conflicts: [],
					hasMore,
					reset: false,
					writesAccepted: !attemptedWrites,
					usage: usage()
				};
			}

			const conflicts: EncryptedEnvelope[] = [];
			for (const upload of uploads) {
				const current = (
					await tx.execute({
						sql: `SELECT seq, id, ciphertext, slot FROM envelopes
						 WHERE account_id = ? AND slot = ?`,
						args: [accountId, upload.slot]
					})
				).rows[0] as unknown as EncryptedEnvelope | undefined;
				if (current && current.id !== upload.id && current.id !== (upload.expectedId ?? null)) {
					conflicts.push(current);
				}
			}
			if (conflicts.length > 0) {
				await this.touchVia(tx, accountId);
				return {
					cursor: Math.max(cursor, account.nextSeq),
					envelopes: [],
					conflicts,
					hasMore: false,
					reset: false,
					writesAccepted: false,
					usage: usage()
				};
			}

			const deletedAt = Date.now();
			for (const deletion of deletions) {
				const previouslyRetained = (
					await tx.execute({
						sql: `SELECT length(ciphertext) AS ciphertextBytes FROM deleted_envelopes
						 WHERE account_id = ? AND slot = ?`,
						args: [accountId, deletion.slot]
					})
				).rows[0] as unknown as { ciphertextBytes: number } | undefined;
				await tx.execute({
					sql: `INSERT OR REPLACE INTO deleted_envelopes(account_id, slot, id, ciphertext, deleted_at)
						SELECT account_id, slot, id, ciphertext, ?
						FROM envelopes
						WHERE account_id = ? AND slot = ? AND id = ?`,
					args: [deletedAt, accountId, deletion.slot, deletion.id]
				});
				const removed = (
					await tx.execute({
						sql: `DELETE FROM envelopes
						WHERE account_id = ? AND slot = ? AND id = ?
						RETURNING length(ciphertext) AS ciphertextBytes`,
						args: [accountId, deletion.slot, deletion.id]
					})
				).rows[0] as unknown as { ciphertextBytes: number } | undefined;
				if (!removed) continue;
				envelopeCount -= 1;
				ciphertextBytes -= removed.ciphertextBytes;
				if (!previouslyRetained) retainedEnvelopeCount += 1;
				retainedCiphertextBytes +=
					removed.ciphertextBytes - (previouslyRetained?.ciphertextBytes ?? 0);
			}

			let sequence = account.nextSeq;
			let added = false;

			for (const upload of uploads) {
				const hasId = (
					await tx.execute({
						sql: 'SELECT 1 AS present FROM envelopes WHERE account_id = ? AND id = ?',
						args: [accountId, upload.id]
					})
				).rows[0];
				if (hasId) continue;
				if (!BASE64URL.test(upload.ciphertext)) {
					throw new Error('Envelope ciphertext is not base64url');
				}
				const prior = (
					await tx.execute({
						sql: `SELECT seq, id, ciphertext, slot FROM envelopes
						 WHERE account_id = ? AND slot = ?`,
						args: [accountId, upload.slot]
					})
				).rows[0] as unknown as EncryptedEnvelope | undefined;
				const projectedCount = envelopeCount + (prior ? 0 : 1);
				const projectedBytes =
					ciphertextBytes + upload.ciphertext.length - (prior?.ciphertext.length ?? 0);
				let projectedStorageBytes = storageBytes(projectedCount, projectedBytes);
				if (projectedStorageBytes > maxAccountBytes && retainedEnvelopeCount > 0) {
					const retainedRows = (
						await tx.execute({
							sql: `SELECT slot, length(ciphertext) AS ciphertextBytes
							 FROM deleted_envelopes WHERE account_id = ? ORDER BY deleted_at ASC, slot ASC`,
							args: [accountId]
						})
					).rows as unknown as Array<{ slot: string; ciphertextBytes: number }>;
					for (const row of retainedRows) {
						await tx.execute({
							sql: 'DELETE FROM deleted_envelopes WHERE account_id = ? AND slot = ?',
							args: [accountId, row.slot]
						});
						retainedEnvelopeCount -= 1;
						retainedCiphertextBytes -= row.ciphertextBytes;
						projectedStorageBytes = storageBytes(projectedCount, projectedBytes);
						if (projectedStorageBytes <= maxAccountBytes) break;
					}
				}
				if (projectedStorageBytes > maxAccountBytes && projectedStorageBytes >= storageBytes()) {
					throw new SyncQuotaExceededError();
				}
				sequence += 1;
				await tx.execute({
					sql: `INSERT INTO envelopes(account_id, slot, seq, id, ciphertext)
					VALUES (?, ?, ?, ?, ?)
					ON CONFLICT(account_id, slot) DO UPDATE SET
						seq = excluded.seq,
						id = excluded.id,
						ciphertext = excluded.ciphertext`,
					args: [accountId, upload.slot, sequence, upload.id, upload.ciphertext]
				});
				envelopeCount = projectedCount;
				ciphertextBytes = projectedBytes;
				added = true;
			}

			const seenAt = Date.now();
			if (added || deletions.length > 0) {
				await tx.execute({
					sql: `
					UPDATE accounts
					SET next_seq = ?, envelope_count = ?, ciphertext_bytes = ?, updated_at = ?, last_seen_at = ?
					WHERE account_id = ?
				`,
					args: [sequence, envelopeCount, ciphertextBytes, seenAt, seenAt, accountId]
				});
			} else {
				await this.touchVia(tx, accountId, seenAt);
			}

			return {
				cursor: Math.max(cursor, sequence),
				envelopes: [],
				conflicts: [],
				hasMore: false,
				reset: false,
				writesAccepted: true,
				usage: usage()
			};
		});
	}

	async deleteAccount(accountId: string): Promise<boolean> {
		await this.db.ready;
		await this.purgeAccountOpsState([accountId]);
		const result = await this.relay.execute({
			sql: 'DELETE FROM accounts WHERE account_id = ?',
			args: [accountId]
		});
		return result.rowsAffected === 1;
	}

	private async purgeAccountOpsState(accountIds: string[]): Promise<void> {
		for (const ids of chunk(accountIds)) {
			const placeholders = ids.map(() => '?').join(', ');
			await this.ops.batch(
				[
					{
						sql: `DELETE FROM reminder_push_devices WHERE account_id IN (${placeholders})`,
						args: ids
					},
					{
						sql: `DELETE FROM reminder_wakes WHERE account_id IN (${placeholders})`,
						args: ids
					},
					{
						sql: `DELETE FROM reminder_wake_deliveries WHERE account_id IN (${placeholders})`,
						args: ids
					}
				],
				'write'
			);
		}
	}

	async touchAccount(accountId: string, now = Date.now()): Promise<void> {
		await this.db.ready;
		await this.touchVia(this.relay, accountId, now);
	}

	private async touchVia(
		client: Client | Transaction,
		accountId: string,
		now = Date.now()
	): Promise<void> {
		await client.execute({
			sql: 'UPDATE accounts SET last_seen_at = ? WHERE account_id = ?',
			args: [now, accountId]
		});
	}

	getQuotas(): SyncQuotas {
		return {
			maxAccountBytes: this.maxAccountBytes
		};
	}

	async operatorUsage(
		options: {
			now?: number;
			staleBefore?: number | null;
		} = {}
	): Promise<OperatorUsage> {
		await this.db.ready;
		const now = options.now ?? Date.now();
		const windows = ACTIVITY_WINDOWS_DAYS;
		const staleBefore = options.staleBefore ?? null;
		const activeSelects = windows
			.map(
				(_, index) =>
					`COALESCE(SUM(CASE WHEN last_seen_at >= ? THEN 1 ELSE 0 END), 0) AS active_${index}`
			)
			.join(',\n');
		const sql = `
			SELECT
				COUNT(*) AS accounts,
				COALESCE(SUM(envelope_count), 0) AS envelopeCount,
				COALESCE(SUM(ciphertext_bytes), 0) AS ciphertextBytes,
				(SELECT COUNT(*) FROM deleted_envelopes) AS retainedEnvelopeCount,
				(SELECT COALESCE(SUM(length(ciphertext)), 0) FROM deleted_envelopes)
					AS retainedCiphertextBytes,
				${activeSelects ? `${activeSelects},` : ''}
				COALESCE(SUM(CASE WHEN last_seen_at < ? THEN 1 ELSE 0 END), 0) AS staleAccounts
			FROM accounts
		`;
		const row = (
			await this.relay.execute({
				sql,
				args: [...windows.map((days) => now - days * 24 * 60 * 60 * 1000), staleBefore ?? 0]
			})
		).rows[0] as Record<string, number>;
		const activeByWindowDays: Record<string, number> = {};
		for (const [index, days] of windows.entries()) {
			activeByWindowDays[String(days)] = row[`active_${index}`] ?? 0;
		}
		return {
			accounts: row.accounts,
			envelopeCount: row.envelopeCount,
			ciphertextBytes: row.ciphertextBytes,
			storageBytes:
				row.ciphertextBytes +
				row.retainedCiphertextBytes +
				(row.envelopeCount + row.retainedEnvelopeCount) * ENVELOPE_STORAGE_OVERHEAD_BYTES,
			activeByWindowDays,
			staleAccounts: staleBefore == null ? 0 : row.staleAccounts
		};
	}

	async deleteInactiveAccounts(staleBefore: number): Promise<number> {
		await this.db.ready;
		const stale = (
			await this.relay.execute({
				sql: 'SELECT account_id AS accountId FROM accounts WHERE last_seen_at < ?',
				args: [staleBefore]
			})
		).rows as unknown as Array<{ accountId: string }>;
		if (stale.length === 0) return 0;
		await this.purgeAccountOpsState(stale.map((row) => row.accountId));
		let deleted = 0;
		for (const ids of chunk(stale.map((row) => row.accountId))) {
			const placeholders = ids.map(() => '?').join(', ');
			const result = await this.relay.execute({
				sql: `DELETE FROM accounts WHERE account_id IN (${placeholders})`,
				args: ids
			});
			deleted += result.rowsAffected;
		}
		return deleted;
	}

	async purgeExpiredDeletedEnvelopes(
		now = Date.now(),
		graceMs = DELETED_SLOT_GRACE_MS
	): Promise<number> {
		await this.db.ready;
		const result = await this.relay.execute({
			sql: 'DELETE FROM deleted_envelopes WHERE deleted_at <= ?',
			args: [now - graceMs]
		});
		return result.rowsAffected;
	}

	/** Register one account-scoped browser endpoint without changing account wakes. */
	async savePushDevice(device: PushDeviceInput): Promise<void> {
		await this.db.ready;
		await withTxn(this.ops, async (tx) => {
			const existing = (
				await tx.execute({
					sql: 'SELECT 1 AS present FROM reminder_push_devices WHERE account_id = ? AND device_id = ?',
					args: [device.accountId, device.deviceId]
				})
			).rows[0];

			await tx.execute({
				sql: 'DELETE FROM reminder_push_devices WHERE endpoint = ? AND (account_id != ? OR device_id != ?)',
				args: [device.endpoint, device.accountId, device.deviceId]
			});
			await tx.execute({
				sql: 'DELETE FROM reminder_push_devices WHERE device_id = ? AND account_id != ?',
				args: [device.deviceId, device.accountId]
			});

			if (!existing) {
				const extras = (
					await tx.execute({
						sql: 'SELECT device_id AS deviceId FROM reminder_push_devices WHERE account_id = ? ORDER BY updated_at ASC',
						args: [device.accountId]
					})
				).rows as unknown as Array<{ deviceId: string }>;
				const overflow = extras.length + 1 - MAX_PUSH_DEVICES;
				if (overflow > 0) {
					for (const row of extras.slice(0, overflow)) {
						await tx.execute({
							sql: 'DELETE FROM reminder_push_devices WHERE account_id = ? AND device_id = ?',
							args: [device.accountId, row.deviceId]
						});
					}
				}
			}

			await tx.execute({
				sql: `
				INSERT INTO reminder_push_devices(
					account_id, device_id, endpoint, p256dh, auth, updated_at
				)
				VALUES (?, ?, ?, ?, ?, ?)
				ON CONFLICT(account_id, device_id) DO UPDATE SET
					endpoint = excluded.endpoint,
					p256dh = excluded.p256dh,
					auth = excluded.auth,
					updated_at = excluded.updated_at
			`,
				args: [
					device.accountId,
					device.deviceId,
					device.endpoint,
					device.p256dh,
					device.auth,
					Date.now()
				]
			});
		});
		await this.touchAccount(device.accountId);
	}

	async replaceReminderWakes(
		accountId: string,
		wakes: ReminderWakeInput[],
		revision?: number
	): Promise<boolean> {
		await this.db.ready;
		const account = (
			await this.relay.execute({
				sql: 'SELECT wake_revision AS wakeRevision FROM accounts WHERE account_id = ?',
				args: [accountId]
			})
		).rows[0] as unknown as { wakeRevision: number } | undefined;
		if (!account || (revision !== undefined && revision < account.wakeRevision)) return false;
		const limitedWakes = wakes.slice(0, MAX_WAKES_PER_ACCOUNT);
		if (revision !== undefined && revision === account.wakeRevision) {
			const current = (
				await this.ops.execute({
					sql: `SELECT wake_id AS id, fire_at AS fireAt FROM reminder_wakes
					 WHERE account_id = ? ORDER BY wake_id ASC, fire_at ASC`,
					args: [accountId]
				})
			).rows as unknown as ReminderWakeInput[];
			const expected = [...limitedWakes].sort((left, right) =>
				left.id < right.id ? -1 : left.id > right.id ? 1 : left.fireAt - right.fireAt
			);
			return JSON.stringify(current) === JSON.stringify(expected);
		}
		await withTxn(this.ops, async (tx) => {
			await tx.execute({
				sql: 'DELETE FROM reminder_wakes WHERE account_id = ?',
				args: [accountId]
			});
			for (const wake of limitedWakes) {
				await tx.execute({
					sql: 'INSERT INTO reminder_wakes(account_id, wake_id, fire_at) VALUES (?, ?, ?)',
					args: [accountId, wake.id, wake.fireAt]
				});
			}
		});
		const now = Date.now();
		if (revision !== undefined) {
			const result = await this.relay.execute({
				sql: 'UPDATE accounts SET wake_revision = ?, updated_at = ?, last_seen_at = ? WHERE account_id = ? AND wake_revision <= ?',
				args: [revision, now, now, accountId, revision]
			});
			if (result.rowsAffected !== 1) return false;
		} else {
			await this.touchAccount(accountId, now);
		}
		return true;
	}

	async claimDueWakes(now: number, limit = 100): Promise<DueWake[]> {
		await this.db.ready;
		return withTxn(this.ops, async (tx) => {
			const rows = (
				await tx.execute({
					sql: `SELECT
					d.account_id AS accountId,
					d.device_id AS deviceId,
					w.wake_id AS wakeId,
					w.fire_at AS fireAt,
					d.endpoint AS endpoint,
					d.p256dh AS p256dh,
					d.auth AS auth
				 FROM reminder_wakes w
				 INNER JOIN reminder_push_devices d ON d.account_id = w.account_id
				 LEFT JOIN reminder_wake_deliveries x
					ON x.account_id = d.account_id
					AND x.device_id = d.device_id
					AND x.wake_id = w.wake_id
				 WHERE w.fire_at <= ?
					AND x.delivered_at IS NULL
					AND (x.claimed_at IS NULL OR x.claimed_at <= ?)
				 ORDER BY w.fire_at ASC, w.wake_id ASC, d.device_id ASC
				 LIMIT ?`,
					args: [now, now - WAKE_CLAIM_LEASE_MS, limit]
				})
			).rows as unknown as DueWake[];
			for (const row of rows) {
				await tx.execute({
					sql: `INSERT INTO reminder_wake_deliveries(
					account_id, device_id, wake_id, claimed_at, delivered_at
				 ) VALUES (?, ?, ?, ?, NULL)
				 ON CONFLICT(account_id, device_id, wake_id) DO UPDATE SET
					claimed_at = excluded.claimed_at,
					delivered_at = NULL`,
					args: [row.accountId, row.deviceId, row.wakeId, now]
				});
			}
			return rows;
		});
	}

	async markWakeDelivered(
		wake: Pick<DueWake, 'accountId' | 'deviceId' | 'wakeId'>,
		now: number
	): Promise<void> {
		await this.db.ready;
		await this.ops.execute({
			sql: `UPDATE reminder_wake_deliveries SET delivered_at = ?
			 WHERE account_id = ? AND device_id = ? AND wake_id = ?`,
			args: [now, wake.accountId, wake.deviceId, wake.wakeId]
		});
	}

	async releaseWakeClaim(wake: Pick<DueWake, 'accountId' | 'deviceId' | 'wakeId'>): Promise<void> {
		await this.db.ready;
		await this.ops.execute({
			sql: `DELETE FROM reminder_wake_deliveries
			 WHERE account_id = ? AND device_id = ? AND wake_id = ? AND delivered_at IS NULL`,
			args: [wake.accountId, wake.deviceId, wake.wakeId]
		});
	}

	async pruneStaleWakes(now: number, retainMs = WAKE_RETAIN_MS): Promise<void> {
		await this.db.ready;
		const cutoff = now - retainMs;
		await withTxn(this.ops, async (tx) => {
			await tx.execute({ sql: 'DELETE FROM reminder_wakes WHERE fire_at < ?', args: [cutoff] });
			await tx.execute({
				sql: `DELETE FROM reminder_wake_deliveries
				 WHERE COALESCE(delivered_at, claimed_at) < ?`,
				args: [cutoff]
			});
		});
	}

	async deletePushDevice(accountId: string, deviceId: string): Promise<void> {
		await this.db.ready;
		await this.ops.execute({
			sql: 'DELETE FROM reminder_push_devices WHERE account_id = ? AND device_id = ?',
			args: [accountId, deviceId]
		});
		await this.touchAccount(accountId);
	}

	async countPushDevices(accountId?: string): Promise<number> {
		await this.db.ready;
		const result = accountId
			? await this.ops.execute({
					sql: 'SELECT COUNT(*) AS count FROM reminder_push_devices WHERE account_id = ?',
					args: [accountId]
				})
			: await this.ops.execute('SELECT COUNT(*) AS count FROM reminder_push_devices');
		return (result.rows[0] as unknown as { count: number }).count;
	}

	async isReady(): Promise<boolean> {
		try {
			await this.db.ready;
			await this.relay.execute('SELECT 1 AS ready');
			await this.ops.execute('SELECT 1 AS ready');
			return true;
		} catch {
			return false;
		}
	}
}

let singleton: SyncStore | undefined;

export function getSyncStore(): SyncStore {
	singleton ??= new SyncStore(getDb(), {
		maxAccountBytes: positiveInteger(
			env.SCRAPSCACHE_SYNC_MAX_ACCOUNT_BYTES,
			DEFAULT_MAX_ACCOUNT_BYTES
		)
	});
	return singleton;
}
